D[41841]={"^Increases your Magic Damage dealt to the enemy by (.-)%%, stacking (.-) times, for (.-)%.%s*$","Aumenta seu dano mágico causado o inimigo em {{1}}%, acumulando-se {{2}} vezes, durante {{3}}."}
D[42103]={"^While active, your next |cffffffffThaumaturgy|r or |cFFFFFFFFGlyphic Ruin|r will now grant you a |cffffffffChapter|r of the same school as your active |cffffffffAttunement|r, causing your next 10 direct spell casts to deal additional school damage to nearby enemies, reduced by (.-)%% for each target hit past the initial%.%s*$","Enquanto está ativo, seu próximo |cffffffffTauturgia|r ou |cFFFFFFFFRuína Glífica|r concederá um |cffffffffCapítulo|r do mesmo tipo que seu |cffffffffSintonia|r ativa, fazendo com que seus próximos 10 conjurações diretos de feitiços causem dano adicional do tipo os inimigos próximos, reduzidos em {{1}}% para cada alvo atingido depois do inicial."}
D[42238]={"^Damage dealt by |cffffffffUnleash Runes|r increased by (.-)%%, stacking (.-) times, for (.-)%.\n\n|cffffffffUnleash Runes|r now deals an additional (.-) Fire Damage for each stack of |cffffffffSearing Codex|r, but expends all stacks on use%.%s*$","O dano causado por |cffffffffAcionar Runas|r aumenta em {{1}}%, acumulando até {{2}} vezes durante {{3}}.\n\n|cffffffffAcionar Runas|r agora causa {{4}} de dano de Fogo adicional para cada acúmulo de |cffffffffCódice Abrasador|r, mas consome todos os acúmulos ao ser usado."}
