D[42537]={"^Increases the spell haste of all party and raid members by (.-)%%%. Does not stack with similar effects%.\n\nIn addition, the range of your Glyphic spells is increased by (.-) yds%.%s*$","Aumenta a aceleração com feitiços de todos os membros do grupo e da raide em {{1}}%. Não acumula com efeitos semelhantes.\n\nAlém disso, o alcance de seus feitiços Glíficos aumenta em {{2}} m."}
D[42744]={"^Increases your Spirit by (.-)%% and reduces spell pushback suffered from damaging attacks by (.-)%%%.%s*$","Aumenta seu Espírito em {{1}}% e reduz em {{2}}% o atraso de conjuração causado por ataques que causam dano."}
D[42774]={"^Harness the power of your runic tattoos, increasing your melee attack speed by (.-)%% for (.-) and causing your next |cffffffffFist of the Ancients|r to strike 2 additional times%.%s*$","Canaliza o poder das suas |cffffffffTatuagens Rúnicas|r, aumentando em {{1}}% sua velocidade de ataque corpo a corpo durante {{2}} e fazendo seu próximo |cffffffffPunho dos Anciãos|r golpear 2 vezes adicionais."}
D[42775]={"^|cffffffffPhase Out|r now lasts an additional (.-) sec, removes all harmful spell effects, and can be used 1 additional time before incurring a cooldown%.%s*$","|cffffffffSair de Fase|r agora dura {{1}} s a mais, remove todos os efeitos mágicos nocivos e pode ser usada mais uma vez antes de entrar em recarga."}
D[42776]={"^|cffffffffPhase Out|r now lasts an additional (.-) sec, removes all harmful spell effects, and can be used 1 additional time within (.-) before incurring a cooldown%.%s*$","|cffffffffSair de Fase|r agora dura {{1}} s a mais, remove todos os efeitos mágicos nocivos e pode ser usada mais uma vez dentro de {{2}} antes de entrar em recarga."}
D[42805]={"^Harness the power of your runic tattoos, causing your next |cffffffffRuneblade|r to trigger |cffffffffPrimeval Carving|r%.%s*$","Canaliza o poder de suas tatuagens rúnicas, fazendo com que sua próxima |cffffffffLâmina Rúnica|r acione |cffffffffEntalhe Primevo|r."}
D[43755]={"^Engrave a fire rune onto your weapon for 1 hour%.\n\nGrants your direct damage dealt a (.-)%% chance to ignite the target, dealing (.-) Fire Damage per stack after (.-)%.%s*$","Grava uma runa de Fogo em sua arma durante 1 hora.\n\nSeu dano direto tem {{1}}% de chance de incendiar o alvo, causando {{2}} de dano de Fogo por acúmulo após {{3}}."}
