T[10534]={"^Melee attacks deal additional Arcane damage and regenerate Mana%.%s*$","Os ataques corpo a corpo causam um adicional dano Arcano e aumentam a mana."}
T[10606]={"^Spellwrath Casting Speed increased by (.-)%%, and Spellwrath no longer clears Aces before generating more%.%s*$","A velocidade de lançamento de |cffffffffIra Mágica|r aumenta em {{1}}%, e ela não remove seus Ases antes de gerar novos."}
T[10611]={"^Damage taken from Displace Familiar increased by (.-)%%%.%s*$","Dano recebido do Deslocar familiar aumenta em {{1}}%"}
T[10892]={"^The Runemaster can set their Hearthstone here%.%s*$","O Mestre de Runicas pode colocar seu Pedra de Retorno aqui."}
T[11071]={"^Destroy the Scrying Orb and teleport the caster to its location%.%s*$","Destrói o Orbe de Escrutínio e teletransporta o conjurador à sua localização."}
T[11367]={"^At (.-) stacks, your next Spellwrath becomes instant cast and free and deals (.-)%% additional damage%.%s*$","Com {{1}} acúmulos, sua próxima |cffffffffIra Mágica|r torna-se instantânea, não custa recursos e causa {{2}}% de dano adicional."}
T[11368]={"^Your next Spellwrath is instant cast and free and deals (.-)%% additional damage%.%s*$","Sua próxima |cffffffffIra Mágica|r é instantânea, não custa recursos e causa {{1}}% de dano adicional."}
T[11380]={"^You can no longer benefit from Magic Tolerance%.%s*$","Já você não pode se beneficiar de Tolerância à Magia."}
T[11470]={"^In addition, your chance to hit is increased by (.-)%% and your spell hit rating is increased by (.-)%% of your Agility%.%s*$","Além disso, sua chance de acertar aumenta em {{1}}% e seu índice de acerto com feitiços aumenta em {{2}}% de seu agilidade."}
T[11677]={"^DOOOOOOOOOM!%s*$","DOOOOOOOOOM!"}
T[12932]={"^Your spells can be cast while moving%.%s*$","Seus feitiços podem lançar-se enquanto se move."}
T[14305]={"^You will be warped to your marked location at the end of the duration%.%s*$","Ao final da duração, você será teletransportado para o local marcado."}
T[14313]={"^|cffffffffSpellwrath|r now generates an Inscribed Rune and make your Runic Familiar unleash a |cffffffffRunic Pulse|r%.|r%s*$","|cffffffffIra Mágica|r agora gera uma Runa Inscrita e faz seu Familiar Rúnico liberar um |cffffffffPulso Rúnico|r.|r"}
T[14396]={"^Can be consumed by Spellsling and |cffffffffPrimordial Pulse|r to deal (.-) Spellfrost Damage and grant you 1 Inscribed Rune%.%s*$","Pode ser consumido por Feitiços e |cffffffffPulso primordial|r para causar {{1}} de dano de Gelo Mágico e conceder a você 1 Runa inscrita."}
T[14397]={"^Can be consumed by Spellsling to deal (.-) Spellfrost Damage and grant you 1 Inscribed Rune%.%s*$","Pode ser consumido por Feitiços para causar {{1}} de dano de Gelo Mágico e conceder a você 1 Runa inscrita."}
T[14479]={"^Grants |cffffffffManastrike|r and auto attacks a (.-)%% chance to generate a stack of |cffffffffPrimordial Energy|r and 1 |cffffffffInscribed Rune|r%.\n\nIncreases spell power by (.-)%% of Intellect%.%s*$","Concede a |cffffffffGolpe Mágico|r e aos ataques automáticos {{1}}% de chance de gerar um acúmulo de |cffffffffEnergia Primordial|r e 1 |cffffffffRuna Inscrita|r.\n\nAumenta o Poder Mágico em {{2}}% do Intelecto."}
T[14609]={"^Reduces the cooldown of |cffffffffWarp|r by (.-) sec and |cffffffffLey Walk|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffDistorção|r em {{1}} s e de |cffffffffCaminhada Ley|r em {{2}} s."}
T[14610]={"^Reduces the cooldown of |cffffffffOpen Riftgate|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffAbrir Portal de Fenda|r em {{1}} s."}
T[14611]={"^Causes |cffffffffManastrike|r to reduce the remaining cooldown of |cffffffffSpellblades|r by (.-) sec%.%s*$","Faz com que |cffffffffGolpe Mágico|r reduz a recarga restante de |cffffffffEspadas Mágicas|r em {{1}} s."}
T[14614]={"^Reduces the cooldown of |cffffffffPrimordial Blast|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffExplosão Primal|r em {{1}} s."}
T[14617]={"^Increases the duration of |cffffffffZenith|r by (.-) sec%.%s*$","Aumenta a duração de |cffffffffZênite|r em {{1}} s."}
T[14619]={"^Reduces the cooldown of |cffffffffSorcerer's Cage|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffJaula do Feiticeiro|r em {{1}} s."}
T[14620]={"^Reduces the cooldown of |cffffffffManastorm|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffTempestade de Mana|r em {{1}} s."}
T[14621]={"^Reduces the cooldown of |cffffffffFastcast|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffLançamento Rápido|r em {{1}} s."}
T[14784]={"^For (.-), your next 10 |cffffffffBrands|r unleashed now deal an additional (.-) Elemental Damage%.%s*$","Durante {{1}}, suas próximas 10 |cffffffffMarcas|r liberadas causam {{2}} de dano Elemental adicional."}
T[14837]={"^Increases the duration of your |cffffffffAtomic Split|r ability by (.-) seconds %(or 2 seconds in combat%), and increases the speed granted by the spell by (.-)%%%.%s*$","Aumenta em {{1}} segundos a duração de |cffffffffFissão Atômica|r (ou 2 segundos em combate) e em {{2}}% a velocidade concedida pelo feitiço."}
T[14878]={"^Displaced%.  Slowed by (.-)%%%.%s*$","Deslocado. Desacelerado em {{1}}%."}
T[14879]={"^Magic Lock now also attempts to steal a beneficial magic effect from its target, lasting up to 2 min%.\n\nIf it succeeds, it also burns (.-) mana from them, causing damage equal to the mana burned, and reduces healing done to the target by (.-)%% for (.-)%.%s*$","Tranca Mágica agora também tenta roubar um efeito mágico benéfico do alvo, que pode durar até 2 min.\n\nSe tiver êxito, também queima {{1}} de mana do alvo, causando dano equivalente à mana queimada e reduzindo em {{2}}% a cura realizada no alvo durante {{3}}."}
T[14883]={"^Reduces damage you take by (.-)%%, increases maximum mana by (.-)%%%.\n\nOnly 1 Aspect can be active at a time%.%s*$","Reduz em {{1}}% o dano que você recebe e aumenta em {{2}}% sua mana máxima.\n\nApenas 1 Aspecto pode estar ativo por vez."}
T[14916]={"^Adds the |cffffffffAce of Primordials|r to your deck, allowing |cffffffffSpellwrath|r to draw it from the random pool%.%s*$","Adiciona |cffffffffCarta do Primal|r a seu baralho, permitindo a |cffffffffIra Mágica|r retirá-la do grupo aleatório de cartas."}
T[15263]={"^Increases the direct damage of your next Shaman Shock by (.-)%% and its duration by (.-) seconds%.\n\nConsuming this buff reduces the cooldown of Stormstrike by 2 seconds and Wind Strike by 1 second%.%s*$","Aumenta em {{1}}% o dano direto do seu próximo Choque Xamânico e aumenta sua duração em {{2}} s.\n\nConsumir este benefício reduz a recarga de |cffffffffGolpe da Tempestade|r em 2 s e de |cffffffffGolpe de Vento|r em 1 s."}
T[16481]={"^Empowered by the twisted magic of the manastorm, this creature leeches power from its nearby allies, increasing its health by (.-)%% and its damage by (.-)%%%.\n\nKilling nearby enemies causes this effect to fade%.%s*$","Fortalecida pela magia distorcida da Tempestade de Mana, esta criatura drena o poder dos aliados próximos, aumentando sua vida em {{1}}% e seu dano em {{2}}%.\n\nMatar os inimigos próximos faz este efeito desaparecer."}
T[16820]={"^Empowered by eldritch energies%. Physical damage taken reduced by %-5%%%. Taking physical damage causes you to phase out%.%s*$","Fortalecido por energias eldricas. O dano Físico recebido é reduzido em -5%\\. Receber dano Físico faz você desfasear."}
T[17217]={"^Seal of Arcane Wrath%s*$","Selo de Raiva Arcana"}
T[18388]={"^Fel%-Shaman Ralakesh is siphoning the elemental power of Air, granting him new abilities%.\n\nAttack speed increased by (.-)%%%.\nMovement speed increased by (.-)%%%.\n\nUnbind the elemental to sever the exchange!%s*$","O Xamã Vil Ralakesh está drenando o poder elemental do Ar e recebendo novas habilidades.\n\nVelocidade de ataque aumentada em {{1}}%.\nVelocidade de movimento aumentada em {{2}}%.\n\nDesvincule o elemental para interromper a transferência!"}
T[18391]={"^Unleashing the thunderous power of Air%.\n\nDealing Nature damage to enemies within 20 yards every 2 seconds%.%s*$","Libera o poder trovejante do Ar.\n\nCausa dano de Natureza aos inimigos em um raio de 20 m a cada 2 s."}
T[18755]={"^You may use Phase Out 1 additional time before it incurs its cooldown%.%s*$","Você pode usar Sair de Fase 1 adicional vez antes de que se ativar sua recarga."}
T[19074]={"^Transformed into Millhouse Manastorm%.%s*$","Transformado em Milhouse Tormentamaná."}
T[19173]={"^Damage taken from Displace Familiar increased by (.-)%%%.%s*$","Dano recebido do Deslocar familiar aumenta em {{1}}%"}
T[19565]={"^Empowered with the power of Air Elementals%.\n\nAttacks have a chance to increase attack speed by (.-)%%, stacks up to 3 times%.%s*$","Potencializado com o poder dos Elementais Aéreos.\n\nOs ataques têm uma chance de aumentar a velocidade de ataque em {{1}}%, acumula até 3 vezes."}
T[20137]={"^Elemental Assassin Earth Shock Proc%s*$","Ativação do assassino elemental Terremoto."}
T[20172]={"^Elemental Assassin Fire SLS%s*$","Assassino Elemental Fogo SLS."}
T[20664]={"^When activated, plays a random assortment of Millhouse Manastorm's most eccentric sayings and vocalizations%s*$","Quando ativada, reproduz aleatoriamente algumas das falas e vocalizações mais excêntricas de Millhouse Manavento."}
T[21042]={"^Empowered with the power of Air Elementals%.\n\nAttacks have a chance to increase attack speed by (.-)%%, stacks up to 3 times%.%s*$","Potencializado com o poder dos Elementais Aéreos.\n\nOs ataques têm uma chance de aumentar a velocidade de ataque em {{1}}%, acumula até 3 vezes."}
T[21460]={"^The demonic energy caused you to grow wings and phase out of the normal world%.%s*$","A energia demoníaca fez você criar asas e sair de fase do mundo normal."}
T[21593]={"^Stabilizing Manastorm Portal%s*$","Portal Estabilizado de Redemoinho de Mana."}
T[21696]={"^Improved stealth%.%s*$","Furtividade aprimorado."}
T[24531]={"^Immune to attacks and spells%.%s*$","Imune aos ataques e feitiços."}
T[25186]={"^Translucent%.%s*$","Translúcido."}

